{
  "question_num": 5,
  "total_marks": 11,
  "title": "Superposition",
  "main_stem": "Light from a laser is used to produce an interference pattern on a screen, as shown in Fig. 5.1. {{figure:fig_5_1}} Fig. 5.1 (not to scale) The light of wavelength $660\\text{ nm}$ is incident normally on two slits that have a separation of $0.44\\text{ mm}$. The double slit is parallel to the screen. The perpendicular distance between the double slit and the screen is $1.8\\text{ m}$. The central bright fringe on the screen is formed at point $O$. The next dark fringe below point $O$ is formed at point $P$. The next bright fringe and the next dark fringe below point $P$ are formed at points $Q$ and $R$ respectively.",
  "parts": [
    {
      "label": "(a)",
      "part_stem": null,
      "text": "The light waves from the two slits are coherent. State what is meant by coherent.",
      "marks": 1,
      "answer_prompt": null,
      "unit": null
    },
    {
      "label": "(b)(i)",
      "part_stem": "For the two light waves superposing at $R$, calculate:",
      "text": "the difference in their path lengths, in nm, from the slits",
      "marks": 1,
      "answer_prompt": "path difference =",
      "unit": "nm"
    },
    {
      "label": "(b)(ii)",
      "part_stem": null,
      "text": "their phase difference.",
      "marks": 1,
      "answer_prompt": "phase difference =",
      "unit": "°"
    },
    {
      "label": "(c)",
      "part_stem": null,
      "text": "Calculate the distance $OQ$.",
      "marks": 3,
      "answer_prompt": "distance OQ =",
      "unit": "m"
    },
    {
      "label": "(d)",
      "part_stem": null,
      "text": "The intensity of the light incident on the double slit is increased without changing the frequency. Describe how the appearance of the fringes after this change is different from, and similar to, their appearance before the change.",
      "marks": 3,
      "answer_prompt": null,
      "unit": null
    },
    {
      "label": "(e)",
      "part_stem": null,
      "text": "The light of wavelength $660\\text{ nm}$ is now replaced by blue light from a laser. State and explain the change, if any, that must be made to the separation of the two slits so that the fringe separation on the screen is the same as it was for light of wavelength $660\\text{ nm}$.",
      "marks": 2,
      "answer_prompt": null,
      "unit": null
    }
  ],
  "markscheme": [
    {
      "label": "(a)",
      "marks": 1,
      "marking_points": [
        {
          "tag": "B1",
          "text": "constant phase difference (between the waves)"
        }
      ]
    },
    {
      "label": "(b)(i)",
      "marks": 1,
      "marking_points": [
        {
          "tag": "A1",
          "text": "990 nm (1.5 × 660)"
        }
      ]
    },
    {
      "label": "(b)(ii)",
      "marks": 1,
      "marking_points": [
        {
          "tag": "A1",
          "text": "540° (1.5 × 360)"
        }
      ]
    },
    {
      "label": "(c)",
      "marks": 3,
      "marking_points": [
        {
          "tag": "C1",
          "text": "use of x = λD / a"
        },
        {
          "tag": "C1",
          "text": "substitution with λ = 660 × 10^-9, D = 1.8, a = 0.44 × 10^-3"
        },
        {
          "tag": "A1",
          "text": "2.7 × 10^-3 m"
        }
      ]
    },
    {
      "label": "(d)",
      "marks": 3,
      "marking_points": [
        {
          "tag": "B1",
          "text": "bright fringes brighter"
        },
        {
          "tag": "B1",
          "text": "dark fringes still dark / same darkness"
        },
        {
          "tag": "B1",
          "text": "same separation / (fringe) spacing"
        }
      ]
    },
    {
      "label": "(e)",
      "marks": 2,
      "marking_points": [
        {
          "tag": "M1",
          "text": "fringe separation ∝ wavelength / separation, so λ / a constant for same x"
        },
        {
          "tag": "A1",
          "text": "decrease separation"
        }
      ]
    }
  ]
}
